const LIMIT = 3900; // safe margin under Telegram's 4096

const items = $input.all().map(i => i.json);

if (items.length === 0) {
  return [{ json: { text: 'No results.' } }];
}

// collect every column across all rows, first-seen order
const cols = [];
for (const row of items) {
  for (const k of Object.keys(row)) {
    if (!cols.includes(k)) cols.push(k);
  }
}

const cell = v => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

const widths = {};
for (const c of cols) {
  widths[c] = Math.max(c.length, ...items.map(i => cell(i[c]).length));
}

const pad  = (v, w) => v.padEnd(w);
const line = vals => cols.map((c, idx) => pad(vals[idx], widths[c])).join('  ');

const header   = line(cols);
const rowLines = items.map(i => line(cols.map(c => cell(i[c]))));

// group rows into chunks that stay under LIMIT, header included each time
const chunks = [];
let current = [header];
let len = header.length + 1;

for (const r of rowLines) {
  const add = r.length + 1;
  // if a single row + header already exceeds the limit, send it alone
  if (header.length + 1 + add > LIMIT) {
    if (current.length > 1) { chunks.push(current.join('\n')); }
    chunks.push([header, r].join('\n'));
    current = [header];
    len = header.length + 1;
    continue;
  }
  if (len + add > LIMIT) {
    chunks.push(current.join('\n'));
    current = [header];
    len = header.length + 1;
  }
  current.push(r);
  len += add;
}
if (current.length > 1) chunks.push(current.join('\n'));

// optional page labels
const total = chunks.length;
return chunks.map((text, idx) => ({
  json: { text: total > 1 ? `(${idx + 1}/${total})\n${text}` : text }
}));
